// Per-visitor identity. No auth system yet — a signed cookie maps each
// visitor to a User row, so every visitor only ever sees their own channels.
// The cookie value IS the User id (cuid-shaped, generated by the client).

import { cookies } from "next/headers";

export const VISITOR_COOKIE = "ct_uid";

export function getVisitorId(): string | undefined {
  const cookieStore = cookies();
  return cookieStore.get(VISITOR_COOKIE)?.value;
}

// Returns an existing visitor id, or creates one and persists it as a cookie.
// Only call from a Server Component / Server Action (needs the request scope).
export function ensureVisitorId(): string {
  const existing = getVisitorId();
  if (existing) return existing;

  const id = generateUserId();
  cookies().set(VISITOR_COOKIE, id, {
    httpOnly: true,
    sameSite: "lax",
    maxAge: 60 * 60 * 24 * 365, // 1 year, so tracked accounts persist
    path: "/",
  });
  return id;
}

// Prisma's default ids are cuid(2)-shaped; ours are uuid(4) — both are
// opaque strings, so sharing one id-space is fine.
function generateUserId(): string {
  return crypto.randomUUID();
}